#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""FEYZULLAH AKILLI CIFTLIK - V33.9.8 MEDIA PLAYER HAZIRLIK
Orijinal 62 dosyalik V33.9.7 TEMA paketinin tamami bu dosyanin icindedir.
Render Build Command: python FEYZULLAH_AKILLI_CIFTLIK_V33_9_8_MEDIA_PLAYER_HAZIRLIK.py --prepare
Render Start Command: uvicorn main:app --host 0.0.0.0 --port $PORT
"""
import argparse, base64, hashlib, io, subprocess, sys, zipfile
from pathlib import Path

_EMBEDDED_ZIP_B64 = r"""

"""
EXPECTED_FILE_COUNT = 63
EXPECTED_SHA256 = "674b05b48a99f7aecdbcb8a05aee8501dd72ec7c73a50f87ed57315fc6665540"

def prepare():
    archive_bytes = base64.b64decode(_EMBEDDED_ZIP_B64)
    if hashlib.sha256(archive_bytes).hexdigest() != EXPECTED_SHA256:
        raise SystemExit("Gomulu arsiv butunluk kontrolu basarisiz!")
    root = Path.cwd().resolve()
    with zipfile.ZipFile(io.BytesIO(archive_bytes)) as zf:
        entries = zf.infolist()
        if len(entries) != EXPECTED_FILE_COUNT:
            raise SystemExit("Dosya sayisi kontrolu basarisiz!")
        for info in entries:
            target = (root / info.filename).resolve()
            if root != target and root not in target.parents:
                raise SystemExit("Guvenli olmayan arsiv yolu: " + info.filename)
        zf.extractall(root)
    req = root / "requirements.txt"
    if req.exists():
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-r", str(req)])
    print("Hazir: 63 dosyanin tamami geri acildi; bagimliliklar kuruldu.")

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--prepare", action="store_true")
    args = parser.parse_args()
    if args.prepare:
        prepare()
    else:
        print("Hazirlik icin --prepare parametresiyle calistirin.")
